/**
 * Refreshes `src/disposable-domains.generated.ts` from the CC0 list maintained at
 * https://github.com/disposable-email-domains/disposable-email-domains. Review the diff before
 * committing: a mainstream provider showing up there would lock its users out of sign-up (add it to
 * `ALLOWED_DOMAINS` in `src/email-guard.ts` instead of editing the generated file).
 *
 *   bun run auth:update-disposable
 */
import { writeFileSync } from "node:fs";

const SOURCE =
  "https://raw.githubusercontent.com/disposable-email-domains/disposable-email-domains/main/disposable_email_blocklist.conf";
const OUTPUT = new URL("../src/disposable-domains.generated.ts", import.meta.url);
const DOMAIN = /^[a-z0-9-]+(\.[a-z0-9-]+)+$/;

const response = await fetch(SOURCE);
if (!response.ok) throw new Error(`GET ${SOURCE} → ${response.status}`);
const domains = [
  ...new Set(
    (await response.text())
      .split("\n")
      .map((line) => line.trim().toLowerCase())
      .filter((line) => line && !line.startsWith("#")),
  ),
].sort();
const invalid = domains.filter((domain) => !DOMAIN.test(domain));
if (invalid.length > 0) throw new Error(`Unexpected entries: ${invalid.slice(0, 5).join(", ")}`);
if (domains.length < 1000) throw new Error(`Only ${domains.length} domains: refusing to write.`);

writeFileSync(
  OUTPUT,
  `// Generated by scripts/update-disposable-domains.ts (bun run auth:update-disposable). Don't edit.
// Source: ${SOURCE} (CC0 1.0).
export const DISPOSABLE_DOMAINS: string = \`
${domains.join("\n")}
\`;
`,
);
console.info(`Wrote ${domains.length} domains to ${OUTPUT.pathname}`);
